from collections import Counter

def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    # Find the dominant diagonal orientation for each foreground color.
    # A repeated diagonal pair marks a line; extend it toward the farther edge.
    background=max(set(v for row in g for v in row), key=lambda v: sum(row.count(v) for row in g))
    for color in set(v for row in g for v in row):
        if color == background:
            continue
        pairs=[]
        counts=Counter()
        for r in range(h):
            for c in range(w):
                if g[r][c] != color:
                    continue
                for dr,dc in ((1,1),(1,-1)):
                    rr,cc=r+dr,c+dc
                    if 0<=rr<h and 0<=cc<w and g[rr][cc]==color:
                        pairs.append((r,c,dr,dc))
                        counts[(dr,dc)]+=1
        if not pairs:
            continue
        best=max(counts.values())
        directions={d for d,n in counts.items() if n==best}
        if len(directions)>1:
            directions={(1,-1)} if (1,-1) in directions else {next(iter(directions))}
        for r,c,dr,dc in pairs:
            if (dr,dc) not in directions:
                continue
            # The two possible continuations lie beyond the pair endpoints.
            # Choose the continuation with more room before the grid edge.
            p1=(r-dr,c-dc)
            p2=(r+2*dr,c+2*dc)
            def room(p,step):
                rr,cc=p; n=0
                while 0<=rr<h and 0<=cc<w:
                    n+=1; rr+=step[0]; cc+=step[1]
                return n
            n1=room(p1,(-dr,-dc))
            n2=room(p2,(dr,dc))
            if n1>=n2:
                rr,cc=p1; sr,sc=-dr,-dc; n=n1
            else:
                rr,cc=p2; sr,sc=dr,dc; n=n2
            for _ in range(n):
                g[rr][cc]=color
                rr+=sr; cc+=sc
    return g
